SELECT ?label ?uri WHERE {
  ?uri a brick:Zone .
  FILTER(STR(?uri) LIKE "Perimeter_top_ZN_4" || STR(?uri) LIKE "Core_top")
  ?uri rdfs:label ?label .
}

SELECT ?zone ?label WHERE {
  ?zone a brick:Zone .
  OPTIONAL { ?zone rdfs:label ?label . }
}

SELECT ?sub ?type WHERE {
  ?type a brick:SubclassOf .
  OPTIONAL { ?type rdfs:label ?label }
  ?type brick:subclassOf ?sub .
} LIMIT 50

SELECT DISTINCT ?type ?label WHERE {
  ?s a ?type .
  OPTIONAL { ?type rdfs:label ?label }
}

SELECT ?z ?label WHERE {
  ?z a brick:HVAC_Zone .
  ?z ref:hasExternalReference ?ref .
  OPTIONAL {?z rdfs:label ?label}
}

SELECT ?point ?label ?tsid WHERE {
  ?point brick:hasLocation ?zone .
  ?zone a brick:HVAC_Zone .
  ?zone rdfs:label ?label .
  ?point ref:hasTimeseriesId ?tsid .
}

SELECT ?zone ?point ?class WHERE {
  ?zone a brick:HVAC_Zone .
  ?point brick:hasLocation ?zone .
  ?point a ?class .
}

